{
 "summary": "Mispaired: the Lean theorem is not the paper's Lemma 5.2. Lean proves the existence of thresholds M, then C₀, then r. For every Λ ≥ M, every C ≥ C₀ and every 0 < δ < r, it gives an entrance profile E for which the reference profiles satisfy a list of bounds on a 'hold region': a source lower bound, a logarithmic slope bound, positivity of p1, a cone margin, and p1(100,η) > 3. The paper's Lemma 5.2 is an induction lemma: it builds smooth order-n extensions of inner solutions with vanishing moments m_n, compact X-support, and support and derivative bounds on the stress T_n. Many objects the Lean statement uses are not shown (holdRegion, referenceProfiles, sourceQ, logSlope, coneSize, CoefficientProfile, window, etc.), so even its intended meaning cannot be fully checked.",
 "glossary": [
  {"decl": "AnalyticInputs", "line": 5, "plain": "A coefficient family together with a radius exceeding its epsilon and a compact set K ⊂ ℂ. K contains every closed ball of that radius centred on the window interval. The axis phase is complex-analytic on a neighbourhood of K, with derivative complexGradient.", "standard_concept": null, "matches_standard": "unclear", "note": "window.interval, CoefficientFamily, axisPhase and complexGradient are not shown."},
  {"decl": "EntranceProfile", "line": 24, "plain": "A coefficient profile satisfying three conditions on the rescaled entrance set: a strict source lower bound (19/20)·L·Λ·χ + 5/2 < Sq, positivity of p1 for p.1 > 0, and a cone size > 9/4 at X = 4/Λ for all |η| ≤ 1.", "standard_concept": null, "matches_standard": "unclear", "note": "entranceSet, Sq, p1 and coneSize are not shown."},
  {"decl": "ReferenceBoundsOnHold", "line": 40, "plain": "On holdRegion, the reference profiles satisfy: a source lower bound with constants 47/50 and 12/5; logSlope ≤ 1; p1 > 0 when p.1 > 0; coneSize > 9/4 when p.1 ≥ 4/Λ; and p1(100, η) > 3 for |η| ≤ 1.", "standard_concept": null, "matches_standard": "unclear", "note": "holdRegion, referenceProfiles, sourceQ and logSlope are not shown."},
  {"decl": "SmallParameters", "line": 59, "plain": "0 < h ≤ 1/1000 and 0 < j ≤ 1/1000.", "standard_concept": "smallness regime for parameters", "matches_standard": "unclear", "note": "Not in excerpt."},
  {"decl": "E", "line": 18, "plain": "heatE plus patch increment.", "standard_concept": null, "matches_standard": "unclear", "note": "Shadowed by the local binder E in the theorem; unused in the statement."},
  {"decl": "M", "line": 37, "plain": "Alias of HeatedOutgoing.M.", "standard_concept": null, "matches_standard": "unclear", "note": "Shadowed by the local binder M in the theorem; unused in the statement."}
 ],
 "lean_claims": [
  {"theorem": "exists_reference_bounds", "line": 71, "plain": "Assume: analytic inputs d; 0 < h, j ≤ 1/1000; σ > 0; P0 smooth; ν > 0; and for every |η| ≤ 1 with |Z(η)| ≤ ν we have χ(η) > 99/100. Then there exists M > 0 such that for all Λ ≥ M there exists C₀ > 0 such that for all C ≥ C₀ there exist an EntranceProfile E for (d, Λ, C) and r > 0 such that for all 0 < δ < r: 2δ < rampLimit, and ReferenceBoundsOnHold holds for E.profile at (Λ, δ)."}
 ],
 "paper_claims": [
  {"ref": "Lemma 5.2", "plain": "There are radii X_a < X_− < X_+ < X_b, independent of n, with the following property. Given lower-order profiles satisfying (5.2), (5.5) and (5.12), the order-n inner solution extends smoothly to X ≥ 0, |η| ≤ 1, agreeing with it on [0, X_−]. The extension satisfies (5.2) and (5.5), has m_n = 0, and has supp_X P_n ⊂ [0, X_+]. V_n/X and F_n/X extend smoothly to X = 0. The stress T_n has the stated support and obeys the derivative bounds (5.13)."}
 ],
 "coverage": [
